    {n:4,name:"Quotation",gate:"Gate 2 · Offer",tagline:"A priced, scoped, defensible offer nobody has to explain afterwards.",pts:["BANTTC revalidated · credit cleared (Lalzare) · PPC slot confirmed (Sutar)","> ₹10 L: 3 options, RJ told · > ₹50 L: RJ approves in writing","From ERP with control number · one-time costs separate · validity stated","Screenrec video · call after · Target/Live — never unassigned"]},
    {n:5,name:"Follow Up",gate:"",tagline:"Stay in the frame without becoming noise.",pts:["Add value — never “just checking in” · always a call to action","Interaction posted in 48 hrs · next action dated, in the calendar","3 contacts → change channel · 5 contacts → change person","30 days static → flag Monday · 60 days → close with a reason code"]},
    {n:6,name:"Closing",gate:"Gate 3 · Commercial",tagline:"Convert without conceding what we cannot afford to concede.",pts:["Trial close: price · deliverables · date · payment terms","Three options on the playbook · limits written before the meeting","Nothing conceded in the room","Non-negotiable: safety compliance · DAP-2020 · dates PPC has not confirmed"]},
    {n:7,name:"Sales Order",gate:"Gate 4 · Contract Review",tagline:"Hand a clean, unambiguous order to operations.",pts:["Review the PO: commercially correct? technically correct? dates valid?","Any “no” → never book it","ERP booking · full TDS · pre-kickoff mail to RJ and PPC","Advance received or LC live before handover"]},
    {n:8,name:"Delivery",gate:"",tagline:"Operations delivers exactly what sales committed. Sales does not disappear at order.",pts:["Weekly update through PPC · status, photos, deadline","Proforma 1 week before · proving batch / first-article check","Payment follow-up · thank-you mail with documents","After-action report · survey"]},
    {n:9,name:"KAM",gate:"",tagline:"The second order should cost a fraction of the first.",pts:["Formal handover · closing documents · testimonial in a letter","AMC · cross-sell · up-sell · spares before the failure","One order → mailer to that industry","New requirement → back to Stage 2 · none found → account is not being managed"]}
